<?php $e = static fn ($v): string => htmlspecialchars((string) ($v ?? ''), ENT_QUOTES, 'UTF-8'); ?>
<div class="admin-academica">
    <div class="d-flex flex-wrap justify-content-between gap-3 mb-4"><div><h1 class="portal-title">Grupo #<?= (int) $grupo['id_grupo'] ?> · <?= $e($grupo['curso']) ?></h1><p class="portal-subtitle mb-0"><?= $e($grupo['instructor']) ?> · <?= $e($grupo['aula']) ?> · <?= $e(ucfirst($grupo['estado'])) ?></p></div><div class="d-flex gap-2 align-self-start"><a href="/admin/grupos" class="btn admin-btn-outline">Volver</a><a href="/admin/grupos?editar=<?= (int) $grupo['id_grupo'] ?>#formulario-grupo" class="btn admin-btn-primary">Editar grupo</a></div></div>
    <section class="portal-card p-4 mb-4"><h2 class="portal-card-title">Horarios y capacidad</h2><p><?= $e($grupo['fecha_inicio']) ?> → <?= $e($grupo['fecha_fin'] ?: 'Sin fin definido') ?> · Capacidad: <?= (int) $grupo['capacidad_maxima'] ?></p><?php foreach ($grupo['horarios'] as $h): ?><p class="mb-1"><?= $e($h['dia_semana'] . ' ' . $h['hora_inicio'] . '–' . $h['hora_fin']) ?></p><?php endforeach; ?><?= !$grupo['horarios'] ? '<p class="admin-muted mb-0">Horario por definir.</p>' : '' ?></section>
    <section class="portal-card overflow-hidden"><h2 class="portal-card-title p-4 mb-0">Matrículas del grupo</h2><div class="table-responsive"><table class="table admin-table align-middle mb-0"><thead><tr><th>ESTUDIANTE</th><th>EMAIL</th><th>FECHA</th><th>MATRÍCULA</th><th>ESTUDIANTE</th></tr></thead><tbody>
        <?php if (!$alumnos): ?><tr><td colspan="5" class="text-center py-4">Todavía no hay matrículas.</td></tr><?php endif; ?>
        <?php foreach ($alumnos as $a): ?><tr><td><a class="admin-edit" href="/admin/estudiantes/<?= (int) $a['id_estudiante'] ?>"><?= $e($a['nombre'] . ' ' . $a['apellido']) ?></a></td><td><?= $e($a['email']) ?></td><td><?= $e($a['fecha']) ?></td><td><?= $e($a['estado']) ?></td><td><?= $e($a['estudiante_estado']) ?></td></tr><?php endforeach; ?>
    </tbody></table></div></section>
</div>
